# Preserve any items already present in the committed data that this script does
# not (re)generate — e.g. subtechniques added directly to the JSON. This keeps
# the bootstrap additive instead of destructive.
matrix_path = ROOT / "src" / "data" / "matrix-data.json"
known_ids = {item["id"] for item in matrix}
if matrix_path.exists():
    existing = json.loads(matrix_path.read_text(encoding="utf-8"))
    for item in existing:
        if item.get("id") not in known_ids:
            matrix.append(item)
            known_ids.add(item["id"])

